import itertools
import random

def is_valid(edges):
    adj = {i: [] for i in range(8)}
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    for i in range(8):
        if not (3 <= len(adj[i]) <= 4):
            return False

    def can_color(node, colors):
        if node == 8:
            return True
        for c in range(3):
            if all(colors[neighbor] != c for neighbor in adj[node] if neighbor < node):
                colors[node] = c
                if can_color(node + 1, colors):
                    return True
        return False

    colors = [-1] * 8
    if not can_color(0, colors):
        return False

    return True

fixed_edges = [(1,7), (0,7)]
all_possible_edges = [(u, v) for u in range(8) for v in range(u+1, 8) if (u, v) not in fixed_edges]

for _ in range(100000):
    num_edges = random.randint(13, 16)
    num_additional = num_edges - 2
    chosen = random.sample(all_possible_edges, num_additional)
    edges = fixed_edges + chosen
    if is_valid(edges):
        # Sort edges to ensure u < v and sorted order
        edges = [tuple(sorted(e)) for e in edges]
        edges.sort()
        print(edges)
        break
